package com.tuap.backend.dominio.entidades;
import java.time.Instant; import java.util.UUID; import com.tuap.backend.auth.*; import jakarta.persistence.*;
@Entity @Table(name="auth_identities",uniqueConstraints=@UniqueConstraint(columnNames={"provider","provider_subject"})) public class AuthIdentity {
 @Id @GeneratedValue(strategy=GenerationType.AUTO) private UUID id; @Column(nullable=false) private UUID userId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Role role; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private AuthProvider provider; @Column(name="provider_subject",nullable=false,length=512) private String providerSubject; private String emailAtLinkTime; @Column(nullable=false) private boolean active=true; @Column(nullable=false,updatable=false) private Instant createdAt; private Instant lastUsedAt;
 protected AuthIdentity(){} public AuthIdentity(UUID u,Role r,AuthProvider p,String subject,String email,Instant now){userId=u;role=r;provider=p;providerSubject=subject;emailAtLinkTime=email;createdAt=now;lastUsedAt=now;} public UUID getUserId(){return userId;} public Role getRole(){return role;} public AuthProvider getProvider(){return provider;} public String getProviderSubject(){return providerSubject;} public String getEmailAtLinkTime(){return emailAtLinkTime;} public boolean isActive(){return active;} public Instant getCreatedAt(){return createdAt;} public Instant getLastUsedAt(){return lastUsedAt;} public void deactivate(){active=false;} public void usedAt(Instant now){lastUsedAt=now;}
}
